PRAGMA foreign_keys=ON;
CREATE TABLE "User" ("id" TEXT PRIMARY KEY NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"refreshTokenHash" TEXT,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Role" ("id" TEXT PRIMARY KEY NOT NULL,"code" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL);
CREATE TABLE "UserRole" ("userId" TEXT NOT NULL,"roleId" TEXT NOT NULL,PRIMARY KEY("userId","roleId"),FOREIGN KEY("userId") REFERENCES "User"("id"),FOREIGN KEY("roleId") REFERENCES "Role"("id"));
CREATE TABLE "StudentProfile" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL UNIQUE,"enrollment" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT NOT NULL,"photoKey" TEXT,FOREIGN KEY("userId") REFERENCES "User"("id"));
CREATE TABLE "CoordinatorProfile" ("id" TEXT PRIMARY KEY NOT NULL,"userId" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,FOREIGN KEY("userId") REFERENCES "User"("id"));
CREATE TABLE "Company" ("id" TEXT PRIMARY KEY NOT NULL,"name" TEXT NOT NULL,"normalizedName" TEXT NOT NULL UNIQUE,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Tce" ("id" TEXT PRIMARY KEY NOT NULL,"number" TEXT NOT NULL UNIQUE,"studentId" TEXT NOT NULL,"companyId" TEXT NOT NULL,"studentEnrollment" TEXT NOT NULL,"studentName" TEXT NOT NULL,"studentEmail" TEXT NOT NULL,"studentPhone" TEXT NOT NULL,"studentPhotoKey" TEXT,"startDate" DATETIME NOT NULL,"endDate" DATETIME NOT NULL,"status" TEXT NOT NULL DEFAULT 'EM_ELABORACAO',"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,FOREIGN KEY("studentId") REFERENCES "StudentProfile"("id"),FOREIGN KEY("companyId") REFERENCES "Company"("id"));
CREATE TABLE "TceDocument" ("id" TEXT PRIMARY KEY NOT NULL,"tceId" TEXT NOT NULL,"type" TEXT NOT NULL DEFAULT 'TCE_PDF',"storageKey" TEXT NOT NULL,"originalName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"sha256" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"uploadedById" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("tceId") REFERENCES "Tce"("id"));
CREATE TABLE "TceStatusHistory" ("id" TEXT PRIMARY KEY NOT NULL,"tceId" TEXT NOT NULL,"fromStatus" TEXT,"toStatus" TEXT NOT NULL,"reason" TEXT,"actorId" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("tceId") REFERENCES "Tce"("id"),FOREIGN KEY("actorId") REFERENCES "User"("id"));
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY NOT NULL,"actorId" TEXT,"tceId" TEXT,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT NOT NULL,"ip" TEXT,"metadata" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("actorId") REFERENCES "User"("id"),FOREIGN KEY("tceId") REFERENCES "Tce"("id"));
CREATE INDEX "Tce_status_createdAt_idx" ON "Tce"("status","createdAt");
CREATE INDEX "Tce_studentId_createdAt_idx" ON "Tce"("studentId","createdAt");
